do $$ declare v_ready integer; begin
select count(*) into v_ready from runtime_config_definitions where definition_key in ('core.api-contract.enforcement','core.api-contract.require-actor-identity','core.api-contract.require-audit-reason','core.api-contract.require-correlation-id','core.api-contract.require-expected-version','core.api-contract.require-idempotency','core.decision.dedup-ttl','core.decision.dedup-window','core.decision.default-routing-policy','core.decision.immediate-task-severities','core.decision.task-escalation-enabled','core.decision.task-min-occurrences','core.fingerprint.default-fields','core.fingerprint.enabled','core.fingerprint.masking.enabled','core.fingerprint.masking.rules','core.fingerprint.policies','core.fingerprint.policy-version','core.runtime-enforcement.disconnect.authorization-scheme','core.runtime-enforcement.disconnect.default-gateway-base-url','core.runtime-enforcement.disconnect.enabled','core.runtime-enforcement.disconnect.gateway-base-urls.gateway-node-001','core.runtime-enforcement.disconnect.gateway-base-urls.gateway-node-002','core.runtime-enforcement.disconnect.gateway-base-urls.gateway-node-003','core.runtime-enforcement.disconnect.gateway-registry-enabled','core.runtime-enforcement.disconnect.gateway-registry-url','core.runtime-enforcement.disconnect.request-timeout') and review_status='MIGRATION_READY' and migration_authorized=true and admin_editable=true;
if v_ready<>27 then raise exception 'C3R2M_ACTIVE_CONSUMER_CLOSURE_INCOMPLETE expected=27 actual=%',v_ready; end if;
if exists(select 1 from runtime_config_definitions where definition_key in ('core.api-contract.enforcement','core.api-contract.require-actor-identity','core.api-contract.require-audit-reason','core.api-contract.require-correlation-id','core.api-contract.require-expected-version','core.api-contract.require-idempotency','core.decision.dedup-ttl','core.decision.dedup-window','core.decision.default-routing-policy','core.decision.immediate-task-severities','core.decision.task-escalation-enabled','core.decision.task-min-occurrences','core.fingerprint.default-fields','core.fingerprint.enabled','core.fingerprint.masking.enabled','core.fingerprint.masking.rules','core.fingerprint.policies','core.fingerprint.policy-version','core.runtime-enforcement.disconnect.authorization-scheme','core.runtime-enforcement.disconnect.default-gateway-base-url','core.runtime-enforcement.disconnect.enabled','core.runtime-enforcement.disconnect.gateway-base-urls.gateway-node-001','core.runtime-enforcement.disconnect.gateway-base-urls.gateway-node-002','core.runtime-enforcement.disconnect.gateway-base-urls.gateway-node-003','core.runtime-enforcement.disconnect.gateway-registry-enabled','core.runtime-enforcement.disconnect.gateway-registry-url','core.runtime-enforcement.disconnect.request-timeout') and config_set_key<>'RUNTIME/CORE/SYSTEM') then raise exception 'C3R2M_CORE_CONFIG_SET_KEY_MISMATCH'; end if;
if exists(select 1 from runtime_config_inventory_governance where configuration_key in ('core.api-contract.enforcement','core.api-contract.require-actor-identity','core.api-contract.require-audit-reason','core.api-contract.require-correlation-id','core.api-contract.require-expected-version','core.api-contract.require-idempotency','core.decision.dedup-ttl','core.decision.dedup-window','core.decision.default-routing-policy','core.decision.immediate-task-severities','core.decision.task-escalation-enabled','core.decision.task-min-occurrences','core.fingerprint.default-fields','core.fingerprint.enabled','core.fingerprint.masking.enabled','core.fingerprint.masking.rules','core.fingerprint.policies','core.fingerprint.policy-version','core.runtime-enforcement.disconnect.authorization-scheme','core.runtime-enforcement.disconnect.default-gateway-base-url','core.runtime-enforcement.disconnect.enabled','core.runtime-enforcement.disconnect.gateway-base-urls.gateway-node-001','core.runtime-enforcement.disconnect.gateway-base-urls.gateway-node-002','core.runtime-enforcement.disconnect.gateway-base-urls.gateway-node-003','core.runtime-enforcement.disconnect.gateway-registry-enabled','core.runtime-enforcement.disconnect.gateway-registry-url','core.runtime-enforcement.disconnect.request-timeout') and status in ('MIGRATED','LEGACY_RETIRED')) then raise exception 'C3R2M_PREMATURE_SINGLE_AUTHORITY_CUTOVER'; end if;
if exists(select 1 from runtime_config_definitions where definition_key in ('core.decision.default-task-capabilities','core.decision.incident-ttl') and (migration_authorized=true or admin_editable=true or review_status<>'RETIRED')) then raise exception 'C3R2M_INACTIVE_CONSUMER_RECLASSIFICATION_FAILED'; end if;
end $$;
